:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --primary: #f5c542;
  --text: #e8e8f0;
  --muted: #9a9ab0;
  --danger: #e05a5a;
  --radius: 0;
  --border: 3px solid #0f0f17;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 24px 16px;
}

.card {
  background: var(--card);
  border: var(--border);
  box-shadow: 8px 8px 0 #0f0f17;
  padding: 32px 24px;
  width: 100%;
  max-width: 520px;
  border-radius: var(--radius);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 1px;
  color: var(--primary);
  text-transform: uppercase;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.95rem;
}

.task-form {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

#task-input {
  flex: 1 1 180px;
  min-width: 0;
  padding: 12px 14px;
  background: #15151f;
  border: var(--border);
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  border-radius: var(--radius);
}

#task-input:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 16px;
  border: var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  background: var(--muted);
  color: #0f0f17;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: transform 0.05s, box-shadow 0.05s;
  box-shadow: 3px 3px 0 #0f0f17;
}

.btn:hover { filter: brightness(1.1); }
.btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #0f0f17; }
.btn:focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; }

.btn-add { background: var(--primary); }

.empty-state {
  color: var(--muted);
  text-align: center;
  margin: 16px 0;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #15151f;
  border: var(--border);
  padding: 10px 12px;
  flex-wrap: wrap;
}

.task-label {
  flex: 1 1 100%;
  min-width: 0;
  overflow-wrap: anywhere;
  font-weight: 600;
}

.task-time {
  font-variant-numeric: tabular-nums;
  font-size: 1.1rem;
  color: var(--primary);
  min-width: 62px;
  text-align: right;
}

.task-actions {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.btn-toggle { background: var(--primary); }
.btn-toggle.running { background: var(--danger); color: #fff; }
.btn-remove { background: var(--muted); }

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .task-actions { margin-left: 0; width: 100%; justify-content: flex-end; }
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;
  var tickInterval = null;
  var runningTaskId = null;

  var form = document.getElementById('task-form');
  var input = document.getElementById('task-input');
  var list = document.getElementById('task-list');
  var emptyState = document.getElementById('empty-state');

  function formatTime(ms) {
    var totalSeconds = Math.floor(ms / 1000);
    var minutes = Math.floor(totalSeconds / 60);
    var seconds = totalSeconds % 60;
    return String(minutes).padStart(2, '0') + ':' + String(seconds).padStart(2, '0');
  }

  function getTask(id) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) return tasks[i];
    }
    return null;
  }

  function stopRunning() {
    if (runningTaskId !== null) {
      var task = getTask(runningTaskId);
      if (task) {
        task.elapsedMs += Date.now() - task.startedAt;
        task.running = false;
      }
      runningTaskId = null;
    }
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  function startTask(id) {
    var task = getTask(id);
    if (!task) return;
    if (runningTaskId === id) return;
    stopRunning();
    task.running = true;
    task.startedAt = Date.now();
    runningTaskId = id;
    tickInterval = setInterval(updateTimes, 250);
    render();
  }

  function stopTask(id) {
    var task = getTask(id);
    if (!task || !task.running) return;
    task.elapsedMs += Date.now() - task.startedAt;
    task.running = false;
    runningTaskId = null;
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
    render();
  }

  function updateTimes() {
    if (runningTaskId === null) return;
    var task = getTask(runningTaskId);
    if (!task) return;
    var timeEl = document.querySelector('[data-time-id="' + task.id + '"]');
    if (timeEl) {
      timeEl.textContent = formatTime(task.elapsedMs + (Date.now() - task.startedAt));
    }
  }

  function removeTask(id) {
    if (runningTaskId === id) stopRunning();
    tasks = tasks.filter(function (t) { return t.id !== id; });
    render();
  }

  function render() {
    list.innerHTML = '';
    emptyState.style.display = tasks.length === 0 ? 'block' : 'none';

    tasks.forEach(function (task) {
      var li = document.createElement('li');
      li.className = 'task-item';

      var label = document.createElement('span');
      label.className = 'task-label';
      label.textContent = task.label;

      var time = document.createElement('span');
      time.className = 'task-time';
      time.setAttribute('data-time-id', String(task.id));
      time.textContent = formatTime(task.elapsedMs + (task.running ? Date.now() - task.startedAt : 0));

      var actions = document.createElement('div');
      actions.className = 'task-actions';

      var toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'btn btn-toggle' + (task.running ? ' running' : '');
      toggle.textContent = task.running ? 'Stop' : 'Start';
      toggle.setAttribute('aria-label', (task.running ? 'Stop' : 'Start') + ' timer for ' + task.label);
      toggle.addEventListener('click', function () {
        if (task.running) stopTask(task.id);
        else startTask(task.id);
      });

      var remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'btn btn-remove';
      remove.textContent = 'Remove';
      remove.setAttribute('aria-label', 'Remove task ' + task.label);
      remove.addEventListener('click', function () { removeTask(task.id); });

      actions.appendChild(toggle);
      actions.appendChild(remove);
      li.appendChild(label);
      li.appendChild(time);
      li.appendChild(actions);
      list.appendChild(li);
    });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    tasks.push({
      id: nextId++,
      label: text,
      elapsedMs: 0,
      running: false,
      startedAt: 0
    });
    input.value = '';
    input.focus();
    render();
  });

  render();
})();
